/* 학습 해설
 * Word At A Time·첫 NUL의 Bit Mask
 * 문자 하나씩 검사하는 대신 machine word 안에 0byte가 있는지 비트 계산으로 찾는 문자열 최적화를 배웁니다.
 * 아래쪽 little-endian generic 분기의 has_zero는 (a-반복01)&~a&반복80으로 0byte 존재 mask를 만듭니다. 이 결과의 borrow 영향까지 고려해 create_zero_mask는 (bits-1)&~bits를 >>7하여 첫 0 이전 byte만 1인 prefix mask를 만듭니다. Find_zero는 그 prefix byte 수를 구합니다. Big-endian 분기는 high_bits/low_bits·별도 prep·상위쪽 분할 탐색·zero_bytemask로 같은 첫 NUL 계약을 다른 bit 배치에서 구현합니다.
 * 실제 architecture의 word-at-a-time header와 word 폭을 확인합니다. Has_zero가 nonzero일 때만 첫 0용 mask 변환을 연결하고 byte-load로 독립 계산한 첫 0 위치와 비교합니다. 이 header가 문자열 pointer 유효성이나 읽을 수 있는 page를 자동 검증하지는 않습니다.
 */
static inline unsigned long has_zero(unsigned long val, unsigned long *data, const struct word_at_a_time *c)
{
	unsigned long rhs = val | c->low_bits;
	*data = rhs;
	return (val + c->high_bits) & ~rhs;
}

#ifndef zero_bytemask
#define zero_bytemask(mask) (~1ul << __fls(mask))
#endif

#else

/*
 * The optimal byte mask counting is probably going to be something
 * that is architecture-specific. If you have a reliably fast
 * bit count instruction, that might be better than the multiply
 * and shift, for example.
 */
struct word_at_a_time {
	const unsigned long one_bits, high_bits;
};

#define WORD_AT_A_TIME_CONSTANTS { REPEAT_BYTE(0x01), REPEAT_BYTE(0x80) }

#ifdef CONFIG_64BIT

