/* 학습 해설
 * 사용자 정수 배열·두 번 파싱과 소유권
 * 사용자 입력의 정수 목록을 개수에 맞게 할당하고 실패한 중간 자료를 정리하는 경로를 읽습니다.
 * memdup_user_nul로 복사한 문자열에서 get_options를 저장 공간 0으로 호출해 개수를 셉니다. 개수+1칸의 int 배열을 kcalloc한 뒤 다시 파싱하여 첫 칸에 개수, 뒤 칸에 값을 저장합니다. 성공 때만 *array를 갱신하고 임시 문자열은 free_buf 경로에서 해제합니다.
 * 반환 0을 확인한 뒤 array[0]과 값 영역을 사용하고 caller가 kfree합니다. get_options의 반환 위치를 여기서는 검사하지 않으므로 뒤 junk까지 엄격히 검증했다고 생각하지 않습니다. 입력 길이·정수 개수·할당 범위를 적절히 제한합니다.
 */
int parse_int_array_user(const char __user *from, size_t count, int **array)
{
	int *ints, nints;
	char *buf;
	int ret = 0;

	buf = memdup_user_nul(from, count);
	if (IS_ERR(buf))
		return PTR_ERR(buf);

	get_options(buf, 0, &nints);
	if (!nints) {
		ret = -ENOENT;
		goto free_buf;
	}

	ints = kcalloc(nints + 1, sizeof(*ints), GFP_KERNEL);
	if (!ints) {
		ret = -ENOMEM;
		goto free_buf;
	}

	get_options(buf, nints + 1, ints);
	*array = ints;

free_buf:

