/* 학습 해설
 * 명령행 로그·Argument NUL을 공백으로
 * 프로세스 인자의 내부 NUL 구분을 표시할 때 읽기 한도와 표현 손실을 확인합니다.
 * PAGE_SIZE 임시 buffer를 GFP_KERNEL로 만들고 get_cmdline으로 PAGE_SIZE-1까지 읽습니다. 읽은 길이 뒤 NUL을 넣고 마지막 연속 NUL을 뒤로 걷습니다. 마지막 non-NUL까지 있는 내부 NUL은 공백으로 바꿉니다. Quotable 복제 후 임시 buffer를 해제합니다.
 * 성공 반환을 확인하고 복제본을 해제합니다. 원래 argv 경계를 복원하거나 재실행할 자료로 쓰지 않습니다. 인자 안 공백과 경계 공백이 같은 표시가 되고 긴 명령행에는 page 한도가 있습니다.
 */
char *kstrdup_quotable_cmdline(struct task_struct *task, gfp_t gfp)
{
	char *buffer, *quoted;
	int i, res;

	buffer = kmalloc(PAGE_SIZE, GFP_KERNEL);
	if (!buffer)
		return NULL;

	res = get_cmdline(task, buffer, PAGE_SIZE - 1);
	buffer[res] = '\0';

	/* Collapse trailing NULLs, leave res pointing to last non-NULL. */
	while (--res >= 0 && buffer[res] == '\0')
		;

	/* Replace inter-argument NULLs. */
	for (i = 0; i <= res; i++)
		if (buffer[i] == '\0')
			buffer[i] = ' ';

	/* Make sure result is printable. */
	quoted = kstrdup_quotable(buffer, gfp);
	kfree(buffer);
	return quoted;
}

