/* 학습 해설
 * 파일 경로 로그·오류 표식과 임시 공간
 * 열린 파일의 경로 조회 실패를 표시 문자열로 바꾸고 임시 공간을 정리합니다.
 * NULL file이면 unknown 표식을 복제합니다. PATH_MAX+11은 삭제된 파일 suffix 공간을 고려합니다. 임시 할당 실패는 no_memory 표식, file_path가 ERR_PTR이면 too_long 표식을 복제합니다. 정상 경로는 quotable로 복제하고 임시 공간을 해제합니다.
 * 표식의 복제도 실패할 수 있어 최종 NULL을 검사합니다. 오류 표식을 실제 pathname과 구분합니다. 모든 file_path 오류의 실제 원인이 길이 초과라고 이 표식만으로 진단하지 않습니다.
 */
char *kstrdup_quotable_file(struct file *file, gfp_t gfp)
{
	char *temp, *pathname;

	if (!file)
		return kstrdup("<unknown>", gfp);

	/* We add 11 spaces for ' (deleted)' to be appended */
	temp = kmalloc(PATH_MAX + 11, GFP_KERNEL);
	if (!temp)
		return kstrdup("<no_memory>", gfp);

	pathname = file_path(file, temp, PATH_MAX + 11);
	if (IS_ERR(pathname))
		pathname = kstrdup("<too_long>", gfp);
	else
		pathname = kstrdup_quotable(pathname, gfp);

	kfree(temp);
	return pathname;
}
EXPORT_SYMBOL_GPL(kstrdup_quotable_file);

