/**
 * skip_spaces - Removes leading whitespace from @str.
 * @str: The string to be stripped.
 *
 * Returns a pointer to the first non-whitespace character in @str.
 */

annotated:
/* 학습 해설
 * 공백 정리·반환 위치와 Allocation 시작
 * 앞뒤 공백을 제거하는 함수가 자료를 이동하는지 내부 pointer를 반환하는지 확인합니다.
 * skip_spaces는 앞 isspace byte를 건너뛰며 자료를 수정하지 않습니다. strim은 strlen 뒤에서 공백을 거꾸로 걷고 첫 trailing 공간을 NUL로 바꿉니다. 앞쪽은 skip_spaces의 내부 주소를 반환합니다. Empty 문자열은 그대로 반환합니다.
 * strim에는 writable buffer를 줍니다. 반환 주소로 내용을 읽되 heap 해제는 보관한 allocation 시작으로 합니다. Byte ctype의 공백과 모든 Unicode 공백을 같은 것으로 설명하지 않습니다.
 */
char *strim(char *s)
{
	size_t size;
	char *end;

	size = strlen(s);
	if (!size)
		return s;

	end = s + size - 1;
	while (end >= s && isspace(*end))
		end--;
	*(end + 1) = '\0';

	return skip_spaces(s);
}
EXPORT_SYMBOL(strim);

