/* 학습 해설
 * 복사와 Padding·목적 길이 기준
 * 고정 폭 binary 필드에 작은 쪽 길이만 복사하고 남은 목적을 padding합니다.
 * dest_len>count이면 count byte를 memcpy하고 남는 dest_len-count를 memset의 pad로 채웁니다. 아니면 dest_len만 복사합니다. 자동 NUL이나 문자열 길이 계산은 없습니다. Pad는 byte 값입니다.
 * Source의 실제 읽을 수 있는 범위와 목적 dest_len을 보장합니다. Overlap은 memcpy 계약상 허용되지 않습니다. 문자열로 쓸 때는 종료 공간과 정책을 별도로 정합니다.
 */
void memcpy_and_pad(void *dest, size_t dest_len, const void *src, size_t count,
		    int pad)
{
	if (dest_len > count) {
		memcpy(dest, src, count);
		memset(dest + count, pad,  dest_len - count);
	} else {
		memcpy(dest, src, dest_len);
	}
}
EXPORT_SYMBOL(memcpy_and_pad);

