/* 학습 해설
 * FORTIFY 보고·Reason 해석과 Panic
 * Overflow wrapper의 진단에서 함수·접근 방향·요청 크기·가용 크기를 읽습니다.
 * CONFIG_FORTIFY_SOURCE 아래 이름 table을 EACH_FORTIFY_FUNC로 만듭니다. Reason에서 함수 번호와 write 방향을 추출하고 UNKNOWN으로 번호를 제한해 조회합니다. WARN은 이름·size·read/write·avail을 출력합니다. __fortify_panic은 report 후 BUG입니다. 빈 overflow-field 함수들은 compile-time 경고 placeholder입니다.
 * 범위 검사는 호출하는 FORTIFY wrapper에 있습니다. 이 보고 함수가 직접 모든 복사를 검사·축소한다고 생각하지 않습니다. 진단을 해당 caller와 연결하고 panic을 정상 복구 반환 API로 쓰지 않습니다.
 */
void __fortify_report(const u8 reason, const size_t avail, const size_t size)
{
	const u8 func = FORTIFY_REASON_FUNC(reason);
	const bool write = FORTIFY_REASON_DIR(reason);
	const char *name;

	name = fortify_func_name[umin(func, FORTIFY_FUNC_UNKNOWN)];
	WARN(1, "%s: detected buffer overflow: %zu byte %s of buffer size %zu\n",
		 name, size, str_read_write(!write), avail);
}
EXPORT_SYMBOL(__fortify_report);

void __fortify_panic(const u8 reason, const size_t avail, const size_t size)
{
	__fortify_report(reason, avail, size);
	BUG();
}
EXPORT_SYMBOL(__fortify_panic);
#endif /* CONFIG_FORTIFY_SOURCE */

