/* 학습 해설
 * 문자열 복제·끝 NUL과 제한 길이
 * 원래 자료를 보존하며 독립 수명의 문자열을 만들 때 길이 계산·끝 NUL·할당 실패를 연결합니다.
 * kstrdup은 NULL이면NULL, 나머지는 strlen+1만큼 할당해 원래 NUL까지 복사합니다. kstrndup은 strnlen(s,max)으로 길이를 제한하고 len+1을 할당해 len만 복사한 뒤 새 NUL을 씁니다. 두 함수는 kmalloc_track_caller로 호출 위치를 연결하며 allocation 실패는NULL입니다.
 * 성공 pointer를 검사해 사용 후 kfree합니다. 제한 복제는 원본 전체가 담겼는지 알려주는 별도 길이 반환이 없습니다. Max를 원본의 실제 읽을 수 있는 한도에 맞추고 len+1 산술·실제 입력 정책도 확인합니다.
 */
char *kstrndup(const char *s, size_t max, gfp_t gfp)
{
	size_t len;
	char *buf;

	if (!s)
		return NULL;

	len = strnlen(s, max);
	buf = kmalloc_track_caller(len+1, gfp);
	if (buf) {
		memcpy(buf, s, len);
		buf[len] = '\0';
	}
	return buf;
}
EXPORT_SYMBOL(kstrndup);

