/* 학습 해설
 * KV Memory 복제·해제 계열과 종료 없음
 * 큰 binary 복제가 가상 연속 allocation을 사용할 수 있을 때 pointer 자료와 물리 배치를 구분합니다.
 * kvmemdup은 kvmalloc(len,gfp) 뒤 성공 pointer에 len을 memcpy합니다. 자료는 caller가 한 연속 가상 범위로 접근할 수 있지만 물리 연속일 필요는 없습니다. 문서는 kvfree를 해제로 지정합니다. 문자열 길이나 NUL을 추가하는 동작은 없습니다.
 * NULL을 검사하고 실제 allocation 계열에 맞게 kvfree합니다. 물리 연속이 필요한 DMA buffer에 결과를 그대로 적합하다고 가정하지 않습니다. 복제 길이는 실제 읽을 수 있는 kernel source 범위여야 합니다.
 */
void *kvmemdup(const void *src, size_t len, gfp_t gfp)
{
	void *p;

	p = kvmalloc(len, gfp);
	if (p)
		memcpy(p, src, len);
	return p;
}
